 def para(t):m.para(t,after=42,line=238)
 para('**Et CNC-bearbejdet emne i aluminium har allerede en værdi, når det når anodiseringslinjen.** Alulines opgave er at beskytte den værdi gennem stabil overfladekvalitet, sporbar proceskontrol og et sikkert arbejdsmiljø. Det kræver en produktionsplan og en daglig dialog mellem operatører, kvalitet og CNC om specifikationer, lagtykkelse og geometriske tolerancer — før fejl bliver til kassation.')
 para('For teamet på 5–6 vil jeg begynde med at forstå anlæggets driftsrutiner, kompetencer, sikkerhed og aktuelle flaskehalse sammen med operatørerne. En enkel plan for bemanding, opgaver og skifteoverdragelse kan samle status på ordrer, stop og afvigelser. Oppetid, OEE, kassation og kvalitet bør først have en fælles baseline; derefter kan teamet og de relevante specialister prioritere forbedringer og følge effekten.')
 para('Sporbarhed, procesdokumentation, kundekrav og gældende ISO-standarder skal indgå i den daglige kontrol. Ved afvigelser vil jeg sikre, at berørte emner holdes tilbage efter Alulines procedure, og at årsag, beslutning, ansvar og opfølgning dokumenteres med kvalitet og CNC. Procesparametre og tolerancer skal fastlægges af de kompetente fagpersoner ud fra kundens specifikationer — ikke ændres på antagelser.')
 para('**Jeg har ikke praktisk erfaring med anodisering, type II/III, indfarvning eller forsegling, og jeg har ikke selv udført titrering, badkontrol eller kemikaliedosering.** Den væsentlige specialviden skal derfor læres. Indtil jeg er kvalificeret, skal analyser, dosering, ændringer og frigivelse varetages af oplærte og bemyndigede medarbejdere efter godkendte instruktioner. Jeg har ledet arbejde med PLC-styrede anlæg; programmering er ikke dokumenteret.')
 para('Grundlaget for ledelse og opfølgning er otte medarbejdere i ELOHVAC, 14 medarbejdere og 11 samtidige projekter i Ventek-Air samt 25 specialister på 37 Novo-projekter med dokumenteret kvalificering og nul kritiske afvigelser ved aflevering. ELOHVACs egne AI-værktøjer til planlægning og kvalitet gav over 40 % produktivitetsløft; det er ikke et resultat fra anodisering.')
 para('Alulines kombination af CNC-bearbejdning og overfladebehandling gør samarbejdet om kundens færdige emne konkret og vigtigt. Jeg vil gerne bidrage med driftsledelse og systematisk opfølgning, mens jeg lærer anodiseringsfaget af teamet. Jeg vil gerne drøfte, om Aluline har mulighed for den oplæring og faglige støtte, som opgaven kræver.')
 m.meta('Med venlig hilsen',after=5);m.meta('Shahram Ajloo · +45 93 99 95 14 · ajlooshahram@gmail.com',after=0)
 m.page_break();m.resume_header(NAME,TITLE,CONTACT,'PRODUKTIONSOPGAVEN — SIKKER DRIFT OG SPORBAR KVALITET')
 m.para('Anodiseringslinjen skal levere ensartet overfladekvalitet på værdifulde CNC-emner med sikker proceskontrol, sporbarhed og tydelig ledelse af 5–6 operatører. Relevant grundlag: ELOHVACs otte medarbejdere og fuldt P&L; Ventek-Airs 14 medarbejdere og 11 projekter; Novo Nordisks 25 specialister, dokumenterede kvalitetskrav og 37 projekter; BIOFOS’ kritiske døgnkontinuerlige drift. Direkte anodisering og kemisk badkontrol er ikke en del af erfaringen.',after=30)
 m.section('SIKKER DRIFT, SPORBAR KVALITET, LÆRING')
 for a,b in [('Daglig drift','Planlæg bemanding og opgaver med operatørerne; følg stop, sikkerhed og åbne handlinger og aftal, hvem der gør hvad.'),('Kvalitet og CNC','Afklar kundespecifikation og kontrolpunkt med CNC og kvalitet; registrér afvigelser og hold berørte emner tilbage efter godkendte procedurer.'),('Faglig indkøring','Lær badstyring, type II/III, indfarvning og forsegling fra kvalificerede kolleger; ingen selvstændig kemisk procesændring uden kompetence og bemyndigelse.')]:m.bullet(a,b,after=10)
 m.section('ERHVERVSERFARING')
 jobs=[('Ejer / teknisk direktør','ELOHVAC ApS · København · maj 2023–nu','8 medarbejdere inkl. 3 lærlinge · fuldt P&L',[('Ledelse og sikkerhed','Planlægger dagligt arbejde, holder 1:1 og står for oplæring og arbejdsmiljøopfølgning for fem elektrikere og tre lærlinge.'),('Opfølgning og forbedring','AI-værktøjer til tidsplaner, kvalitetstjek og KPI-overblik gav dokumenteret produktivitetsløft over 40 %.')]),('Medejer og CTO / teknisk ansvarlig, AI-afdeling','Data Power Consultant ApS · København · 2024–nov. 2026 · sideløbende med ELOHVAC','4–10 personer · virksomheden ophørt',[('Tekniske løsninger','Ledede udvikling af tekniske og industrielle applikationer fra krav og integration til dokumentation og overdragelse.')]),('Senior commissioning engineer / projektleder, elsystemer','Novo Nordisk A/S · nov. 2022–jul. 2024','37 samtidige CAPEX-projekter · 25 specialister',[('Kvalitet og koordinering','FAT/SAT og IQ/OQ/PQ i GMP-miljø med dokumentation og nul kritiske afvigelser ved aflevering; koordinerede engineering, indkøb og anlæg.')]),('Projekt- og værkstedsleder','Ventek-Air · jan. 2022–nov. 2022','14 medarbejdere · 11 samtidige projekter',[('Plan og opfølgning','Daglig kapacitetsstyring, tavlemøder og flaskehalsanalyse; fulgte fremdrift og sikkerhed på tværs af projekter.')]),('Drifts- og vedligeholdelsesleder / værkstedstekniker','BIOFOS, Lynetten · aug. 2017–jan. 2022','Kritisk 24/7-drift',[('Stabilitet og sikkerhed','Vedligehold og fejlfinding på elektriske og mekaniske anlæg; SCADA, LOTO, risikovurdering og 5S/PDCA.')]),('Elektromekaniker / produktionsteamleder','ARJ Engineering · dec. 2003–mar. 2010','12 mekanikere og teknikere · maskinværksted',[('Team og produktionsopgaver','Vagtplanlægning, materialekoordinering og målstyring; diagnose og reparation af industrielt el- og mekanisk udstyr.')])]
