 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Elautoriseret maskinmester, LV/MV/HV','Sikkerhedsstyrelsen · 2023'),('PRINCE2 certificeret projektleder','AXELOS / PeopleCert'),('El- og maskinteknisk design, elteknik','Tehran Technical University · EQF 6 · 2000–2003')]:m.edu(a,b)
 m.para('**Metoder:** Lean og Six Sigma anvendt i praksis, ikke certificeret; 5S, PDCA, risikovurdering og dokumenteret kvalitetsopfølgning. **Systemer:** SAP ERP, Excel og SCADA; ledelse af arbejde med PLC-styrede anlæg. **Sprog:** dansk og professionelt engelsk; persisk.',after=20)
 rows=[('Daglig ledelse og planlægning af 5–6 operatører','ELOHVAC: daglig ledelse, 1:1 og oplæring for fem elektrikere og tre lærlinge; Ventek-Air: planlægning af 14 personer på 11 projekter.'),('Stabil drift, fejlfinding og procesoptimering','BIOFOS: 24/7-drift og fejlfinding på el- og mekaniske anlæg; Ventek-Air: flaskehalsanalyse. Anodiseringsprocessens konkrete driftsparametre kræver oplæring.'),('Type II/III, indfarvning og forsegling','Ingen praktisk anodiseringserfaring. Skal lære type II og type III samt indfarvning og forsegling hos kvalificerede kolleger, før selvstændigt procesansvar kan vurderes.'),('PLC-styret og fuldautomatisk anlæg','Har ledet arbejde med PLC-styrede anlæg; konkret programmering er ikke dokumenteret. Vil lære linjens automatisering og samarbejde med kompetente teknikere.'),('Kemikalier, dosering, procesbad og titrering','Ingen praktisk titrering, badkontrol eller kemikaliedosering. Kvalificerede medarbejdere skal udføre og frigive analyser og ændringer efter Alulines godkendte instruktioner.'),('Kvalitetssystem, ISO, sporbarhed og dokumentation','Novo: FAT/SAT, IQ/OQ/PQ og dokumentation i GMP; nul kritiske afvigelser ved aflevering. Alulines ISO-krav og konkret sporbarhed skal læres og følges.'),('SPC, procesdata og afvigelser','Erfaring med kvalitetsdokumentation og afvigelser; konkret statistisk proceskontrol (SPC) er ikke dokumenteret. Vil lære metoden og følge aftalte kontrolgrænser med kvalitetsteamet.'),('CNC, lagtykkelse og geometriske tolerancer','Ingen dokumenteret praktisk ansvar for anodiseringens mikrontolerancer. Vil afklare krav og målinger med CNC og kvalitet, før emner frigives efter virksomhedens regler.'),('OEE, oppetid, spild og kassation','BIOFOS: kritisk drift; Ventek-Air: flaskehalsanalyse. Vil etablere baseline og følge OEE, oppetid, kassation og afvigelser uden at love udokumenterede mål.'),('Teknisk uddannelse og faglig støtte','B.Tech i Technology Management and Mechanical Engineering og elautoriseret maskinmester; ikke uddannet kemiker eller overfladebehandler. Anodiseringskompetence kræver konkret oplæring.'),('Sikkerhed, trivsel og samarbejde','ELOHVAC: oplæring og arbejdsmiljøopfølgning for otte medarbejdere; BIOFOS: LOTO og risikovurdering. Kemikaliehåndtering følger godkendte instruktioner og kompetencekrav.'),('Dansk og engelsk','Dansk og professionelt engelsk anvendes til at kommunikere med medarbejdere og samarbejdspartnere; arbejdets instruktioner og kundekrav skal forstås og følges.')]
 m.models_table('OPGAVEN — ERFARING OG OPLÆRING',('Krav i rollen','Erfaring eller sikker første tilgang'),rows,widths=(2500,7846))
